const assert=require("assert"),{haversineDistanceKm:haversineDistanceKm,optimizeRoute:optimizeRoute,tourLengthKm:tourLengthKm,formatDistance:formatDistance,formatDuration:formatDuration,buildCacheKey:buildCacheKey}=require("./../frontend/route-planner/route-planner.js");let passed=0;function test(e,t){try{t(),console.log(`  PASS  ${e}`),passed++}catch(t){console.error(`  FAIL  ${e}`),console.error(`        ${t.message}`),process.exitCode=1}}const delhi={id:"delhi",lat:28.6139,lng:77.209},agra={id:"agra",lat:27.1767,lng:78.0081},jaipur={id:"jaipur",lat:26.9124,lng:75.7873},mumbai={id:"mumbai",lat:19.076,lng:72.8777};console.log("../frontend/route-planner/route-planner.js unit tests"),test("haversineDistanceKm: Delhi to Agra is roughly 200km",()=>{const e=haversineDistanceKm(delhi,agra);assert.ok(e>180&&e<220,`expected ~200km, got ${e.toFixed(1)}km`)}),test("haversineDistanceKm: distance to self is zero",()=>{assert.strictEqual(haversineDistanceKm(delhi,delhi),0)}),test("haversineDistanceKm: is symmetric",()=>{const e=haversineDistanceKm(delhi,mumbai),t=haversineDistanceKm(mumbai,delhi);assert.ok(Math.abs(e-t)<1e-9)}),test("optimizeRoute: keeps the first stop fixed",()=>{const e=optimizeRoute([delhi,mumbai,agra,jaipur]);assert.strictEqual(e[0].id,delhi.id)}),test("optimizeRoute: returns the same set of stops (no drops/dupes)",()=>{const e=[delhi,mumbai,agra,jaipur],t=optimizeRoute(e),a=e.map(e=>e.id).sort(),s=t.map(e=>e.id).sort();assert.deepStrictEqual(s,a)}),test("optimizeRoute: never produces a longer tour than the naive input order",()=>{const e=[delhi,mumbai,agra,jaipur],t=tourLengthKm(e),a=tourLengthKm(optimizeRoute(e));assert.ok(a<=t+1e-9)}),test("optimizeRoute: is a no-op for 2 or fewer stops",()=>{assert.deepStrictEqual(optimizeRoute([delhi]),[delhi]),assert.deepStrictEqual(optimizeRoute([delhi,agra]),[delhi,agra])}),test("formatDistance: formats to one decimal with km suffix",()=>{assert.strictEqual(formatDistance(203.456),"203.5 km")}),test("formatDuration: formats sub-hour durations as minutes",()=>{assert.strictEqual(formatDuration(45),"45 min")}),test("formatDuration: formats multi-hour durations as h/m",()=>{assert.strictEqual(formatDuration(125),"2h 5m")}),test("buildCacheKey: is stable and order-sensitive",()=>{const e=buildCacheKey(["delhi","agra"],"road"),t=buildCacheKey(["agra","delhi"],"road");assert.notStrictEqual(e,t),assert.strictEqual(buildCacheKey(["delhi","agra"],"road"),e)}),console.log(`\n${passed} test(s) passed.`);